{"sql":"CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id INTEGER,
    target_inventory_id INTEGER,
    part_to_transfer_num VARCHAR,
    color_to_transfer_id INTEGER,
    quantity_to_transfer INTEGER,
    transfer_reason VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT AS $$
DECLARE
    source_qty INTEGER;
    target_qty INTEGER;
    source_exists BOOLEAN;
    target_exists BOOLEAN;
    part_exists BOOLEAN;
    color_exists BOOLEAN;
BEGIN
    -- Lock source and target inventory rows for update
    PERFORM 1 FROM lego_inventories WHERE inventory_id = source_inventory_id FOR UPDATE;
    PERFORM 1 FROM lego_inventories WHERE inventory_id = target_inventory_id FOR UPDATE;

    -- Validation A: Check existence
    SELECT EXISTS (SELECT 1 FROM lego_inventories WHERE inventory_id = source_inventory_id) INTO source_exists;
    IF NOT source_exists THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Source inventory does not exist');
        RAISE EXCEPTION 'Source inventory % does not exist', source_inventory_id;
    END IF;

    SELECT EXISTS (SELECT 1 FROM lego_inventories WHERE inventory_id = target_inventory_id) INTO target_exists;
    IF NOT target_exists THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Target inventory does not exist');
        RAISE EXCEPTION 'Target inventory % does not exist', target_inventory_id;
    END IF;

    SELECT EXISTS (SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num) INTO part_exists;
    IF NOT part_exists THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Part does not exist');
        RAISE EXCEPTION 'Part % does not exist', part_to_transfer_num;
    END IF;

    SELECT EXISTS (SELECT 1 FROM lego_colors WHERE color_id = color_to_transfer_id) INTO color_exists;
    IF NOT color_exists THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Color does not exist');
        RAISE EXCEPTION 'Color % does not exist', color_to_transfer_id;
    END IF;

    -- Business Rules Validation
    IF source_inventory_id = target_inventory_id THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Source and target inventories cannot be the same');
        RAISE EXCEPTION 'Source and target inventories cannot be the same';
    END IF;

    IF quantity_to_transfer < 1 THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Quantity to transfer must be at least 1');
        RAISE EXCEPTION 'Quantity to transfer must be at least 1';
    END IF;

    IF quantity_to_transfer > 500 THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Quantity to transfer exceeds maximum limit of 500');
        RAISE EXCEPTION 'Quantity to transfer exceeds maximum limit of 500';
    END IF;

    -- Check source inventory quantity (non-spare row)
    SELECT quantity FROM lego_inventories
    WHERE inventory_id = source_inventory_id
      AND part_num = part_to_transfer_num
      AND color_id = color_to_transfer_id
      AND is_spare = false
    INTO source_qty;

    IF source_qty IS NULL THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Source inventory does not have the part/color combination');
        RAISE EXCEPTION 'Source inventory does not have the part/color combination';
    END IF;

    IF source_qty < quantity_to_transfer THEN
        INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
        VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', 'Insufficient quantity in source inventory');
        RAISE EXCEPTION 'Insufficient quantity in source inventory';
    END IF;

    -- Deduct quantity from source
    UPDATE lego_inventories
    SET quantity = quantity - quantity_to_transfer
    WHERE inventory_id = source_inventory_id
      AND part_num = part_to_transfer_num
      AND color_id = color_to_transfer_id
      AND is_spare = false;

    -- Delete source row if quantity becomes zero
    DELETE FROM lego_inventories
    WHERE inventory_id = source_inventory_id
      AND part_num = part_to_transfer_num
      AND color_id = color_to_transfer_id
      AND is_spare = false
      AND quantity = 0;

    -- Check target inventory for existing row
    SELECT quantity FROM lego_inventories
    WHERE inventory_id = target_inventory_id
      AND part_num = part_to_transfer_num
      AND color_id = color_to_transfer_id
      AND is_spare = false
    INTO target_qty;

    IF target_qty IS NULL THEN
        -- Insert new row
        INSERT INTO lego_inventories(inventory_id, part_num, color_id, quantity, is_spare)
        VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, false);
    ELSE
        -- Update existing row
        UPDATE lego_inventories
        SET quantity = quantity + quantity_to_transfer
        WHERE inventory_id = target_inventory_id
          AND part_num = part_to_transfer_num
          AND color_id = color_to_transfer_id
          AND is_spare = false;
    END IF;

    -- Log successful transfer
    INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status)
    VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'success');

    RETURN FORMAT('Successfully transferred %s parts (%s, color_id: %s) from inventory %s to inventory %s. Reason: %s',
                  quantity_to_transfer, part_to_transfer_num, color_to_transfer_id, source_inventory_id, target_inventory_id, transfer_reason);
EXCEPTION
    WHEN OTHERS THEN
        -- On any error, log failure if not already logged
        IF NOT FOUND THEN
            INSERT INTO inventory_transfer_log (source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message)
            VALUES (source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', SQLERRM);
        END IF;
        RAISE;
END;
$$ LANGUAGE plpgsql;"}
